#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# GENERATED BY AN LLM: Claude (Anthropic), 2026-11-26.
# ---------------------------------------------------------------------------
# The tile coding / RBF experiments that used to be hard-coded cases in
# apps/run_q_learning.cpp, one ./build/run_q_learning command each, with the same
# settings and CSV names (results/<name>_<timestamp>.csv).
#
#   tools/run_experiments.sh <case> [<case> ...]
#   tools/run_experiments.sh list
#
# Tuning cases (tc_* , rbf_alpha_sweep, rbf_sigma_sweep): 3 seeds, --epsilon 0. The
# original tuning runs were made before exploration existed in the training loop, so they
# were greedy. The greedy tie-break was changed on 2026-11-23 (ties now go to HOLD), so a
# rerun reproduces the settings, not identical numbers.
# Comparison cases (cmp_*): 10 seeds, epsilon 0.02, the program's defaults. One case per
# algorithm and feature set: cmp_tc_rbf_qlearning, cmp_tc_rbf_qlearning_reduced,
# cmp_tc_rbf_sarsa, cmp_tc_rbf_sarsa_reduced. The CSV names are unchanged
# (cmp-tc-final, ...; Sarsa runs have -sarsa), so tools/plot_final.py still finds them.
# Changed 2026-11-26: cmp_tc_rbf and cmp_tc_rbf_reduced renamed to cmp_tc_rbf_qlearning and
# cmp_tc_rbf_qlearning_reduced; cmp_tc_rbf_sarsa split into cmp_tc_rbf_sarsa (13 state
# variables) and cmp_tc_rbf_sarsa_reduced (4 state variables).
# ---------------------------------------------------------------------------
set -euo pipefail
cd "$(dirname "$0")/.."
RQ=./build/run_q_learning
TUNE=(--episodes 20000 --seeds 3 --epsilon 0)

tc_gamma_sweep() {      # tiles 10, alpha 0.1
  for g in 0.9 0.99 1; do
    $RQ --approx tc "${TUNE[@]}" --tiles 10 --alpha 0.1 --gamma "$g" --name "tc-gamma-tune-$g"
  done
}

tc_alpha_sweep() {      # tiles 10, gamma 0.99
  for a in 0.1 0.3 0.5 0.6 0.7 0.8; do
    $RQ --approx tc "${TUNE[@]}" --tiles 10 --alpha "$a" --gamma 0.99 --name "tc-alpha-tune-$a"
  done
}

tc_tile_sweep() {       # alpha 0.6, gamma 0.99
  for t in 10 20 40; do
    $RQ --approx tc "${TUNE[@]}" --tiles "$t" --alpha 0.6 --gamma 0.99 --name "tc-tile-tune-$t"
  done
}

tc_cmp_keeper() {       # 1 learning keeper (+2 hand-coded) vs 3 learning keepers
  for n in 1 3; do
    $RQ --approx tc "${TUNE[@]}" --tiles 20 --alpha 0.6 --gamma 0.99 --learners "$n" --name "tc-keeper-tune-$n"
  done
}

rbf_alpha_sweep() {     # 200 centres, sigma 0.025
  for a in 0.4 0.5 0.6 0.7; do
    $RQ --approx rbf "${TUNE[@]}" --centres 200 --sigma 0.025 --alpha "$a" --gamma 0.99 --name "rbf-alpha-tune-$a"
  done
}

rbf_sigma_sweep() {     # 200 centres, alpha 0.6
  for s in 0.005 0.01 0.025 0.04; do
    $RQ --approx rbf "${TUNE[@]}" --centres 200 --sigma "$s" --alpha 0.6 --gamma 0.99 --name "rbf-sd-tune-$s"
  done
}

cmp_tc_rbf_qlearning() {          # final comparison, Q-learning, 13 state variables
  $RQ --approx tc --algo qlearn --name cmp-tc-final
  $RQ --approx rbf --algo qlearn --name cmp-rbf-final
}

cmp_tc_rbf_qlearning_reduced() {  # final comparison, Q-learning, 4 state variables
  $RQ --approx tc --algo qlearn --features reduced --name cmp-tc-reduced-final
  $RQ --approx rbf --algo qlearn --features reduced --name cmp-rbf-reduced-final
}

cmp_tc_rbf_sarsa() {              # final comparison, Sarsa, 13 state variables
  $RQ --approx tc --algo sarsa --name cmp-tc-sarsa-final
  $RQ --approx rbf --algo sarsa --name cmp-rbf-sarsa-final
}

cmp_tc_rbf_sarsa_reduced() {      # final comparison, Sarsa, 4 state variables
  $RQ --approx tc --algo sarsa --features reduced --name cmp-tc-sarsa-reduced-final
  $RQ --approx rbf --algo sarsa --features reduced --name cmp-rbf-sarsa-reduced-final
}

CASES=(tc_gamma_sweep tc_alpha_sweep tc_tile_sweep tc_cmp_keeper rbf_alpha_sweep rbf_sigma_sweep
       cmp_tc_rbf_qlearning cmp_tc_rbf_qlearning_reduced cmp_tc_rbf_sarsa cmp_tc_rbf_sarsa_reduced)

if [[ $# -eq 0 || "$1" == "list" ]]; then
  echo "usage: tools/run_experiments.sh <case> [<case> ...]"
  printf '  %s\n' "${CASES[@]}"
  exit 0
fi

[[ -x $RQ ]] || { echo "build first: make" >&2; exit 1; }
for c in "$@"; do
  if [[ " ${CASES[*]} " == *" $c "* ]]; then
    echo "=== $c ==="
    "$c"
  else
    echo "unknown case: $c (tools/run_experiments.sh list)" >&2
    exit 1
  fi
done
